        this.onVisibility = () => {
          const now = performance.now();
          if (document.hidden) {
            this.capturePhase(now);
            this.visible = false;
            if (this.frameHandle) {
              cancelAnimationFrame(this.frameHandle);
              this.frameHandle = 0;
            }
            return;
          }

          this.visible = true;
          if (this.motionEnabled) {
            const speed = this.config.field.motionSpeed;
            this.startTime = speed > 0 && this.phaseTime !== null
              ? now - (this.phaseTime / speed) * 1000
              : now;
          }
          this.render(now, true);
          this.schedule();
        };
        this.onMotionPreference = (event) => this.setMotion(!event.matches);
        window.addEventListener("resize", this.onResize, { passive: true });
        document.addEventListener("visibilitychange", this.onVisibility);
        this.motionPreference.addEventListener("change", this.onMotionPreference);
        this.available = true;
        this.resize();
        this.uploadConfig();
        this.schedule();
      } catch (error) {
        this.error = error instanceof Error ? error.message : String(error);
        this.available = false;
        this.gl = null;
        document.documentElement.classList.add("field-fallback");
      }
    }

    resize() {
      if (!this.available) return;
      const pixelRatio = Math.min(window.devicePixelRatio || 1, 1.5);
      const width = Math.max(1, Math.round(this.canvas.clientWidth * pixelRatio));
      const height = Math.max(1, Math.round(this.canvas.clientHeight * pixelRatio));
      if (this.canvas.width !== width || this.canvas.height !== height) {
        this.canvas.width = width;
        this.canvas.height = height;
        this.gl.viewport(0, 0, width, height);
      }
    }

    applyFallbackConfig(config) {
      document.documentElement.style.setProperty("--field-fallback-background", fallbackBackground(config));
    }

    uploadConfig() {
      if (!this.available) return;
      const gl = this.gl;
      const config = this.config;
      const sourceColors = Array.isArray(config.colors) ? config.colors.slice(0, MAX_COLORS) : [];
      const fallbackColor = sourceColors[0] || {
        oklch: config.base.oklch,
        intensity: 0,
        peakOpacity: 0,
        fieldScale: config.field.scale,
        phase: [0, 0]
      };
      const colors = sourceColors.slice();
      while (colors.length < MAX_COLORS) colors.push(fallbackColor);
      const colorValues = colors.flatMap((entry) => oklchToLinearRgb(entry.oklch));
      const strengthValues = colors.map((entry) => entry.intensity * entry.peakOpacity * 3.0);
      const fieldScaleValues = colors.map((entry) => entry.fieldScale);
      const phaseValues = colors.flatMap((entry) => entry.phase);
      gl.useProgram(this.program);
      gl.uniform1f(this.locations.seed, config.seed);
      gl.uniform1f(this.locations.mode, config.mode === "obsidian" ? 1 : 0);
      gl.uniform1f(this.locations.overall, config.overallColorIntensity);
      gl.uniform1f(this.locations.colorCount, sourceColors.length);
      gl.uniform1f(this.locations.scale, config.field.scale);
      gl.uniform1f(this.locations.octaves, config.field.octaves);
      gl.uniform1f(this.locations.warp, config.field.warpStrength);
      gl.uniform1f(this.locations.dither, config.field.ditherStrength);
      gl.uniform1f(this.locations.luminanceCap, config.field.luminanceCap);
      gl.uniform3fv(this.locations.base, new Float32Array(oklchToLinearRgb(config.base.oklch)));
      gl.uniform3fv(this.locations.colors, new Float32Array(colorValues));
      gl.uniform1fv(this.locations.strengths, new Float32Array(strengthValues));
      gl.uniform1fv(this.locations.fieldScales, new Float32Array(fieldScaleValues));
      gl.uniform2fv(this.locations.phases, new Float32Array(phaseValues));
    }

    capturePhase(now) {
      if (this.motionEnabled) {
        this.phaseTime = ((now - this.startTime) / 1000) * this.config.field.motionSpeed;
      } else if (this.phaseTime === null) {
        this.phaseTime = this.config.field.staticTime;
      }
      return this.phaseTime;
    }

    updateConfig(config) {
      const now = performance.now();
      this.capturePhase(now);
      this.config = config;
      this.applyFallbackConfig(config);
      this.uploadConfig();
      this.render(now, true);
    }

    setMotion(enabled) {
      if (enabled === this.motionEnabled) {
        const now = performance.now();
        if (!enabled) this.capturePhase(now);
        this.render(now, true);
        return;
      }
      const now = performance.now();
      const phase = this.capturePhase(now);
      this.motionEnabled = enabled;
      if (enabled) {
        const speed = this.config.field.motionSpeed;
        this.startTime = speed > 0 ? now - (phase / speed) * 1000 : now;
        this.schedule();
      } else {
        this.render(now, true);
      }
    }

    schedule() {
      if (!this.available || !this.visible || this.frameHandle) return;
      this.frameHandle = requestAnimationFrame((now) => {
        this.frameHandle = 0;
        this.render(now, false);
        if (this.motionEnabled) this.schedule();
      });
    }

    render(now, force) {
      if (!this.available) return;
      if (!force && now - this.lastFrame < 50) {
        this.schedule();
        return;
      }
      this.lastFrame = now;
      this.resize();
      const elapsed = this.capturePhase(now);
      this.gl.uniform2f(this.locations.resolution, this.canvas.width, this.canvas.height);
      this.gl.uniform1f(this.locations.time, elapsed);
      this.gl.drawArrays(this.gl.TRIANGLES, 0, 6);
    }
  }

  window.SpectralField = SpectralField;
})();

(function () {
  "use strict";

  const config = window.SPECTRAL_THEME;
  const canvas = document.querySelector("#spectral-field");
  const field = new window.SpectralField(canvas, config);
  const panel = document.querySelector("#parameter-panel");
  const panelToggle = document.querySelector("#parameter-toggle");
  const panelClose = document.querySelector("#parameter-close");
  const controls = document.querySelector("#parameter-controls");
  const exportButton = document.querySelector("#export-parameters");
  const copyButton = document.querySelector("#copy-parameters");
  const motionButton = document.querySelector("#motion-toggle");
  const menuButton = document.querySelector("#menu-toggle");
  const sidebar = document.querySelector("#sidebar");
  const liveStatus = document.querySelector("#live-status");
  const defaultConfig = JSON.parse(JSON.stringify(config));

  function formatNumber(value, digits = 2) {
    return Number(value).toFixed(digits);
  }

  function applyThemeMetadata() {
    document.documentElement.dataset.mode = config.mode;
    document.querySelectorAll("[data-theme-name]").forEach((node) => {
      node.textContent = config.label;
    });
    document.querySelector("#preset-value").textContent = config.preset;
    document.querySelector("#seed-value").textContent = String(config.seed);
    document.querySelector("#renderer-value").textContent = field.available ? "WebGL · live" : "CSS · fallback";
  }

  function renderControls() {
    controls.replaceChildren();

    const overall = document.createElement("div");
    overall.className = "parameter-block parameter-master";
    overall.innerHTML = `
      <div class="parameter-heading">
        <div>
          <span class="parameter-kicker">全局色度预算</span>
          <strong>总体彩色强度</strong>
        </div>
        <output for="overall-intensity">${formatNumber(config.overallColorIntensity)}</output>
      </div>
      <input id="overall-intensity" type="range" min="0" max="1" step="0.01" value="${config.overallColorIntensity}" aria-label="总体彩色强度">
      <div class="range-labels"><span>中性基材</span><span>校准上限</span></div>
    `;
    controls.append(overall);

    const overallInput = overall.querySelector("input");
    overallInput.addEventListener("input", () => {
      config.overallColorIntensity = Number(overallInput.value);
      overall.querySelector("output").value = formatNumber(config.overallColorIntensity);
      field.updateConfig(config);
      announce(`总体彩色强度 ${formatNumber(config.overallColorIntensity)}`);
    });

    config.colors.forEach((color, index) => {
      const row = document.createElement("div");
      row.className = "parameter-block color-parameter";
      row.innerHTML = `
        <div class="parameter-heading">
          <div class="color-name">
            <span class="color-chip" style="--chip:${color.srgbFallback}"></span>
            <div>
              <strong>${color.label}</strong>
              <span class="parameter-kicker">OKLCH ${formatNumber(color.oklch.l)} ${formatNumber(color.oklch.c, 3)} ${formatNumber(color.oklch.h, 0)}</span>
            </div>
          </div>
          <output for="color-${index}">${formatNumber(color.intensity)}</output>
        </div>
        <input id="color-${index}" type="range" min="0" max="1" step="0.01" value="${color.intensity}" aria-label="${color.label}强度">
        <dl class="parameter-facts">
          <div><dt>峰值 α</dt><dd>${formatNumber(color.peakOpacity, 3)}</dd></div>
          <div><dt>空间尺度</dt><dd>${formatNumber(color.fieldScale)}</dd></div>
          <div><dt>相位</dt><dd>${color.phase.map((value) => formatNumber(value)).join(" / ")}</dd></div>
        </dl>
      `;
      controls.append(row);
      const input = row.querySelector("input");
      input.addEventListener("input", () => {
        color.intensity = Number(input.value);
        row.querySelector("output").value = formatNumber(color.intensity);
        field.updateConfig(config);
        announce(`${color.label}强度 ${formatNumber(color.intensity)}`);
      });
    });
  }

  function serializableConfig() {
    return {
      ...config,
      validationCapabilities: {
        modelVision: "runtime-check-required",
        screenshotCapture: "runtime-check-required",
        deterministicPixelMetrics: "runtime-check-required",
        visualVerificationMode: "unverified"
      }
    };
  }

  function downloadParameters() {
    const blob = new Blob([JSON.stringify(serializableConfig(), null, 2)], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement("a");
    anchor.href = url;
    anchor.download = `${config.mode}-parameters.json`;
    document.body.append(anchor);
    anchor.click();
    anchor.remove();
    URL.revokeObjectURL(url);
    announce("参数 JSON 已导出");
  }

  async function copyParameters() {
    try {
      await navigator.clipboard.writeText(JSON.stringify(serializableConfig(), null, 2));
      announce("参数 JSON 已复制");
    } catch (_error) {
      announce("当前环境无法访问剪贴板，请使用导出 JSON");
    }
  }

  function announce(message) {
    liveStatus.textContent = message;
  }

  function setPanel(open) {
    panel.dataset.open = String(open);
    panel.setAttribute("aria-hidden", String(!open));
    panel.toggleAttribute("inert", !open);
    panel.inert = !open;
    panelToggle.setAttribute("aria-expanded", String(open));
    if (open) panelClose.focus();
  }

  setPanel(panel.dataset.open === "true");
  panelToggle.addEventListener("click", () => setPanel(panel.dataset.open !== "true"));
  panelClose.addEventListener("click", () => {
    setPanel(false);
    panelToggle.focus();
  });
  exportButton.addEventListener("click", downloadParameters);
  copyButton.addEventListener("click", copyParameters);

  const isMobileViewport = () => window.matchMedia("(max-width: 760px)").matches;
  let sidebarOpen = sidebar.dataset.open === "true";
  function setSidebar(open) {
    sidebarOpen = Boolean(open);
    const mobile = isMobileViewport();
    const visible = !mobile || sidebarOpen;
    sidebar.dataset.open = String(visible);
    sidebar.setAttribute("aria-hidden", String(!visible));
    sidebar.toggleAttribute("inert", !visible);
    sidebar.inert = !visible;
    menuButton.setAttribute("aria-expanded", String(mobile && sidebarOpen));
    menuButton.setAttribute("aria-label", visible ? "关闭导航菜单" : "打开导航菜单");
  }
  setSidebar(sidebarOpen);
  window.addEventListener("resize", () => setSidebar(sidebarOpen), { passive: true });

  const motionPreference = window.matchMedia("(prefers-reduced-motion: reduce)");
  let motionPausedByUser = false;
  let motionEnabled = false;
  function applyMotion(announceChange = false) {
    motionEnabled = !motionPreference.matches && !motionPausedByUser;
    const enabled = motionEnabled;
    field.setMotion(enabled);
    motionButton.setAttribute("aria-pressed", String(!enabled));
    motionButton.disabled = motionPreference.matches;
    motionButton.querySelector("span").textContent = motionPreference.matches
      ? "系统减少动态"
      : enabled ? "暂停环境" : "恢复环境";
    if (announceChange) {
      announce(motionPreference.matches
        ? "已遵循系统减少动态偏好"
        : enabled ? "环境动画已恢复" : "环境动画已暂停");
    }
  }
  motionButton.addEventListener("click", () => {
    motionPausedByUser = motionEnabled;
    applyMotion(true);
  });
  motionPreference.addEventListener("change", () => applyMotion(true));
  applyMotion();

  menuButton.addEventListener("click", () => {
    setSidebar(!sidebarOpen);
  });

  document.querySelectorAll(".nav-item").forEach((button) => {
    button.addEventListener("click", () => {
      document.querySelectorAll(".nav-item").forEach((item) => item.removeAttribute("aria-current"));
      button.setAttribute("aria-current", "page");
      document.querySelector("#page-location").textContent = button.dataset.location;
      if (isMobileViewport()) setSidebar(false);
    });
  });

  document.querySelectorAll(".record-row").forEach((row) => {
    row.addEventListener("click", () => {
      document.querySelectorAll(".record-row").forEach((item) => item.removeAttribute("aria-selected"));
      row.setAttribute("aria-selected", "true");
      document.querySelector("#record-title").textContent = row.dataset.title;
      document.querySelector("#record-time").textContent = row.dataset.time;
      announce(`已选择 ${row.dataset.title}`);
    });
  });

  const tabs = Array.from(document.querySelectorAll("[role='tab']"));
  function activateTab(tab, focus = false) {
    tabs.forEach((item) => {
      const selected = item === tab;
      item.setAttribute("aria-selected", String(selected));
      item.tabIndex = selected ? 0 : -1;
    });
    document.querySelector("#detail-copy").textContent = tab.dataset.copy;
    if (focus) tab.focus();
  }
  tabs.forEach((tab, index) => {
    tab.addEventListener("click", () => {
      activateTab(tab);
    });
    tab.addEventListener("keydown", (event) => {
      let targetIndex = null;
      if (event.key === "ArrowRight") targetIndex = (index + 1) % tabs.length;
      if (event.key === "ArrowLeft") targetIndex = (index - 1 + tabs.length) % tabs.length;
      if (event.key === "Home") targetIndex = 0;
      if (event.key === "End") targetIndex = tabs.length - 1;
      if (targetIndex === null) return;
      event.preventDefault();
      activateTab(tabs[targetIndex], true);
    });
  });
  const selectedTab = tabs.find((tab) => tab.getAttribute("aria-selected") === "true") || tabs[0];
  if (selectedTab) activateTab(selectedTab);

  document.querySelector("#reset-parameters").addEventListener("click", () => {
    Object.assign(config, JSON.parse(JSON.stringify(defaultConfig)));
    renderControls();
    field.updateConfig(config);
    announce("参数已恢复为模板预设");
  });

  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && panel.dataset.open === "true") {
      setPanel(false);
      panelToggle.focus();
    }
  });

  applyThemeMetadata();
  renderControls();
})();

#!/usr/bin/env python3
"""Parse the data-only subset used by Liuguang theme manifests."""

from __future__ import annotations

import json
import pathlib
import re
from dataclasses import dataclass


MAX_MANIFEST_BYTES = 256 * 1024
MAX_NESTING_DEPTH = 64


class ManifestSyntaxError(ValueError):
    """Raised when a manifest contains code or unsupported JavaScript syntax."""


@dataclass(frozen=True)
class Token:
    kind: str
    value: str
    offset: int


TOKEN_RE = re.compile(
    r"""
    (?P<whitespace>\s+)
  | (?P<line_comment>//[^\r\n]*)
  | (?P<block_comment>/\*.*?\*/)
  | (?P<string>"(?:\\["\\/bfnrt]|\\u[0-9A-Fa-f]{4}|[^"\\\x00-\x1f])*")
  | (?P<number>-?(?:0|[1-9][0-9]*)(?:\.[0-9]+)?(?:[eE][+-]?[0-9]+)?)
  | (?P<identifier>[A-Za-z_$][A-Za-z0-9_$]*)
  | (?P<punctuation>[{}\[\]:,;=.])
    """,
    re.VERBOSE | re.DOTALL,
)


def tokenize(source: str) -> list[Token]:
    tokens: list[Token] = []
    offset = 0
    while offset < len(source):
        match = TOKEN_RE.match(source, offset)
        if match is None:
            raise ManifestSyntaxError(f"unsupported syntax at byte offset {offset}")
        kind = match.lastgroup
        if kind not in {"whitespace", "line_comment", "block_comment"}:
            tokens.append(Token(kind or "unknown", match.group(0), offset))
        offset = match.end()
    tokens.append(Token("eof", "", len(source)))
    return tokens


class Parser:
    def __init__(self, source: str) -> None:
        self.tokens = tokenize(source)
        self.index = 0

    @property
    def current(self) -> Token:
        return self.tokens[self.index]

    def take(self, value: str | None = None, kind: str | None = None) -> Token:
        token = self.current
        if value is not None and token.value != value:
            raise ManifestSyntaxError(
                f"expected {value!r} at byte offset {token.offset}, found {token.value!r}"
            )
        if kind is not None and token.kind != kind:
            raise ManifestSyntaxError(
                f"expected {kind} at byte offset {token.offset}, found {token.value!r}"
            )
        self.index += 1
        return token

    def accept(self, value: str) -> bool:
        if self.current.value != value:
            return False
        self.index += 1
        return True

    def parse(self) -> dict:
        self.take("window")
        self.take(".")
        self.take("SPECTRAL_THEME")
        self.take("=")
        value = self.parse_value(0)
        self.accept(";")
        self.take(kind="eof")
        if not isinstance(value, dict):
            raise ManifestSyntaxError("SPECTRAL_THEME must be an object")
        return value

    def parse_value(self, depth: int):
        if depth > MAX_NESTING_DEPTH:
            raise ManifestSyntaxError("manifest nesting limit exceeded")
        token = self.current
        if token.value == "{":
            return self.parse_object(depth + 1)
        if token.value == "[":
            return self.parse_array(depth + 1)
        if token.kind == "string":
            self.index += 1
            return json.loads(token.value)
        if token.kind == "number":
            self.index += 1
            try:
                return (
                    float(token.value)
                    if any(mark in token.value for mark in ".eE")
                    else int(token.value)
                )
            except ValueError as error:
                raise ManifestSyntaxError("numeric literal exceeds the supported range") from error
        if token.kind == "identifier" and token.value in {"true", "false", "null"}:
            self.index += 1
            return {"true": True, "false": False, "null": None}[token.value]
        raise ManifestSyntaxError(
            f"only data literals are allowed at byte offset {token.offset}; found {token.value!r}"
        )

    def parse_object(self, depth: int) -> dict:
        result: dict = {}
        self.take("{")
        if self.accept("}"):
            return result
        while True:
            token = self.current
            if token.kind == "identifier":
                key = self.take(kind="identifier").value
            elif token.kind == "string":
                key = json.loads(self.take(kind="string").value)
            else:
                raise ManifestSyntaxError(
                    f"object keys must be identifiers or strings at byte offset {token.offset}"
                )
            if key in result:
                raise ManifestSyntaxError(f"duplicate object key: {key}")
            self.take(":")
            result[key] = self.parse_value(depth)
            if self.accept("}"):
                return result
            self.take(",")
            if self.accept("}"):
                return result

    def parse_array(self, depth: int) -> list:
        result: list = []
        self.take("[")
        if self.accept("]"):
            return result
        while True:
            result.append(self.parse_value(depth))
            if self.accept("]"):
                return result
            self.take(",")
            if self.accept("]"):
                return result


def parse_manifest(source: str) -> dict:
    return Parser(source).parse()


def load_manifest(path: pathlib.Path) -> dict:
    with path.open("rb") as manifest:
        raw = manifest.read(MAX_MANIFEST_BYTES + 1)
    if len(raw) > MAX_MANIFEST_BYTES:
        raise ManifestSyntaxError(
            f"manifest exceeds the {MAX_MANIFEST_BYTES}-byte size limit"
        )
    try:
        source = raw.decode("utf-8-sig")
    except UnicodeDecodeError as error:
        raise ManifestSyntaxError("manifest must be valid UTF-8") from error
    return parse_manifest(source)
